45	template <typename T>
46	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
47	{
48	    if constexpr (std::is_same_v<T, bfloat16_t>) {
49	        return AscendC::RoundMode::CAST_ROUND;
50	    }
51	    return AscendC::RoundMode::CAST_NONE;
52	}
