54	template <typename T>
55	__aicore__ inline void CastInputToFloat(
56	    AscendC::LocalTensor<float> &dst,
57	    AscendC::LocalTensor<T> &src,
58	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
59	    int32_t count)
60	{
61	    if constexpr (std::is_same_v<T, float>) {
62	        dst = src.template ReinterpretCast<float>();
63	    } else {
64	        dst = castBuf.Get<float>();
65	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
66	        AscendC::PipeBarrier<PIPE_V>();
67	    }
68	}
