83	template <typename T>
84	__aicore__ inline void CastOutputBack(
85	    AscendC::LocalTensor<T> &out,
86	    AscendC::LocalTensor<float> &src,
87	    int32_t count)
88	{
89	    if constexpr (!std::is_same_v<T, float>) {
90	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
91	        AscendC::PipeBarrier<PIPE_V>();
92	    }
93	}
