95	// =========================================================================
96	// Strategy 1: merge_n — N <= 1024, merge kMergeRowFactor rows into one tile
97	// =========================================================================
98	
99	template <typename dataType>
100	class AddRmsNormDynamicQuantMergeNKernel {
101	public:
102	    __aicore__ inline void Init(
103	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma,
104	        GM_ADDR smooth1, GM_ADDR smooth2,
105	        GM_ADDR y1, GM_ADDR y2, GM_ADDR x_add_out,
106	        GM_ADDR scale1, GM_ADDR scale2,
107	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
108	        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
109	        float inv127)
110	    {
111	        this->M = M;
112	        this->N = N;
113	        this->blockM = blockM;
114	        this->usedCoreNum = usedCoreNum;
115	        this->tasksPerCore = tasksPerCore;
116	        this->rowFactor = rowFactor;
117	        this->eps = eps;
118	        this->invN = invN;
119	        this->inv127 = inv127;
120	
121	        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
122	        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
123	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
124	        smooth1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth1), N);
125	        smooth2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth2), N);
126	        y1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y1), static_cast<uint64_t>(M) * N);
127	        y2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y2), static_cast<uint64_t>(M) * N);
128	        xAddGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_add_out), static_cast<uint64_t>(M) * N);
129	        scale1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale1), M);
130	        scale2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale2), M);
131	
132	        if ASCEND_IS_AIV { InitAivBuffers(); }
133	    }
134	
135	    __aicore__ inline void InitAivBuffers()
136	    {
137	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
138	        rowLoops_ = subBlockRows_ / rowFactor;
139	        const int32_t tileElems = kMergeRowFactor * N;
140	
141	        pipe.InitBuffer(x1InQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
142	        pipe.InitBuffer(x2InQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
143	        pipe.InitBuffer(y1OutQueue_, BUFFER_NUM, tileElems * sizeof(int8_t));
144	        pipe.InitBuffer(y2OutQueue_, BUFFER_NUM, tileElems * sizeof(int8_t));
145	        pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
146	        pipe.InitBuffer(scale1OutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(float));
147	        pipe.InitBuffer(scale2OutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(float));
148	
149	        // Pre-load static buffers: gamma, smooth1, smooth2 (broadcast to kMergeRowFactor rows)
150	        pipe.InitBuffer(gamma1DBuf_, N * sizeof(dataType));
151	        pipe.InitBuffer(gammaTileBuf_, tileElems * sizeof(float));
152	        pipe.InitBuffer(gammaBcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
153	        pipe.InitBuffer(smooth1_1DBuf_, N * sizeof(dataType));
154	        pipe.InitBuffer(smooth1TileBuf_, tileElems * sizeof(float));
155	        pipe.InitBuffer(smooth1BcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
156	        pipe.InitBuffer(smooth2_1DBuf_, N * sizeof(dataType));
157	        pipe.InitBuffer(smooth2TileBuf_, tileElems * sizeof(float));
158	        pipe.InitBuffer(smooth2BcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
159	
160	        // Compute buffers
161	        pipe.InitBuffer(tempBufA_, tileElems * sizeof(float));
162	        pipe.InitBuffer(tempBufB_, tileElems * sizeof(float));
163	        pipe.InitBuffer(tempBufC_, tileElems * sizeof(float));
164	        pipe.InitBuffer(xAddFp32Buf_, tileElems * sizeof(float));
165	        pipe.InitBuffer(quantHalfBuf_, tileElems * sizeof(half));  // intermediate half buffer for float->int8 cast
166	        pipe.InitBuffer(reduceTmpBuf_, 2 * tileElems * sizeof(uint8_t));
167	        pipe.InitBuffer(bcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
168	        pipe.InitBuffer(sumBuf_, kMergeRowFactor * sizeof(float));
169	        pipe.InitBuffer(rstdBuf_, kMergeRowFactor * sizeof(float));
170	        pipe.InitBuffer(scaleBuf_, kMergeRowFactor * sizeof(float));
171	        pipe.InitBuffer(maxAbsBuf_, kMergeRowFactor * sizeof(float));
172	
173	        // Cast buffers for fp16/bf16
174	        if constexpr (!std::is_same_v<dataType, float>) {
175	            pipe.InitBuffer(x1CastBuf_, tileElems * sizeof(float));
176	            pipe.InitBuffer(x2CastBuf_, tileElems * sizeof(float));
177	            pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
178	            pipe.InitBuffer(smooth1CastBuf_, N * sizeof(float));
179	            pipe.InitBuffer(smooth2CastBuf_, N * sizeof(float));
180	            pipe.InitBuffer(xAddCastBuf_, tileElems * sizeof(float));
181	        }
182	
183	        // Pre-load & broadcast gamma
184	        const uint32_t gammaSrcShape[2] = {1U, static_cast<uint32_t>(N)};
185	        const uint32_t gammaDstShape[2] = {
186	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
187	        gammaInLocal_ = gamma1DBuf_.Get<dataType>();
188	        LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
189	        AscendC::PipeBarrier<PIPE_MTE2>();
190	        AscendC::PipeBarrier<PIPE_ALL>();
191	        CastInputToFloat<dataType>(gammaFp32Local_, gammaInLocal_, gammaCastBuf_, N);
192	        gammaTileLocal_ = gammaTileBuf_.Get<float>();
193	        gammaBcastTmpLocal_ = gammaBcastTmpBuf_.Get<uint8_t>();
194	        AscendC::PipeBarrier<PIPE_ALL>();
195	        AscendC::Broadcast<float, 2, 0>(gammaTileLocal_, gammaFp32Local_,
196	            gammaDstShape, gammaSrcShape, gammaBcastTmpLocal_);
197	        AscendC::PipeBarrier<PIPE_V>();
198	    }
199	
200	    __aicore__ inline void Process()
201	    {
202	        if ASCEND_IS_AIV {
203	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
204	            const int subBlockIdx = AscendC::GetSubBlockIdx();
205	
206	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
207	                const int bx = coreIdx * tasksPerCore + localIdx;
208	                if (bx >= (M + blockM - 1) / blockM) { continue; }
209	
210	                for (int r = 0; r < rowLoops_; ++r) {
211	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
212	                    const int validRows = M - rowBase;
213	                    if (validRows > 0) {
214	                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
215	                    }
216	                }
217	            }
218	        }
219	    }
220	
221	private:
222	    static constexpr int kMergeRowFactor = 8;
223	
224	    __aicore__ inline void CopyInX1(int32_t rowBase, int32_t count)
225	    {
226	        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
227	        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
228	        x1InQueue_.EnQue(x1InLocal_);
229	    }
230	
231	    __aicore__ inline void CopyInX2(int32_t rowBase, int32_t count)
232	    {
233	        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
234	        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
235	        x2InQueue_.EnQue(x2InLocal_);
236	    }
237	
238	    __aicore__ inline void CopyOutY1(int32_t rowBase, int32_t count)
239	    {
240	        y1OutLocal_ = y1OutQueue_.DeQue<int8_t>();
241	        StoreUbToGm(y1GM_[static_cast<uint64_t>(rowBase) * N], y1OutLocal_, static_cast<uint32_t>(count));
242	        y1OutQueue_.FreeTensor(y1OutLocal_);
243	    }
244	
245	    __aicore__ inline void CopyOutY2(int32_t rowBase, int32_t count)
246	    {
247	        y2OutLocal_ = y2OutQueue_.DeQue<int8_t>();
248	        StoreUbToGm(y2GM_[static_cast<uint64_t>(rowBase) * N], y2OutLocal_, static_cast<uint32_t>(count));
249	        y2OutQueue_.FreeTensor(y2OutLocal_);
250	    }
251	
252	    __aicore__ inline void CopyOutXAdd(int32_t rowBase, int32_t count)
253	    {
254	        xAddOutLocal_ = xAddOutQueue_.DeQue<dataType>();
255	        StoreUbToGm(xAddGM_[static_cast<uint64_t>(rowBase) * N], xAddOutLocal_, static_cast<uint32_t>(count));
256	        xAddOutQueue_.FreeTensor(xAddOutLocal_);
257	    }
258	
259	    __aicore__ inline void CopyOutScale1(int32_t rowBase, int32_t count)
260	    {
261	        scale1OutLocal_ = scale1OutQueue_.DeQue<float>();
262	        StoreUbToGm(scale1GM_[rowBase], scale1OutLocal_, static_cast<uint32_t>(count));
263	        scale1OutQueue_.FreeTensor(scale1OutLocal_);
264	    }
265	
266	    __aicore__ inline void CopyOutScale2(int32_t rowBase, int32_t count)
267	    {
268	        scale2OutLocal_ = scale2OutQueue_.DeQue<float>();
269	        StoreUbToGm(scale2GM_[rowBase], scale2OutLocal_, static_cast<uint32_t>(count));
270	        scale2OutQueue_.FreeTensor(scale2OutLocal_);
271	    }
272	
273	    // Pre-load and broadcast smooth 1D to tile shape (kMergeRowFactor x N)
274	    __aicore__ inline void PreloadSmooth(
275	        AscendC::GlobalTensor<dataType> &gmSrc,
276	        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf1D,
277	        AscendC::TBuf<AscendC::TPosition::VECCALC> &bufTile,
278	        AscendC::TBuf<AscendC::TPosition::VECCALC> &bufBcastTmp,
279	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
280	        AscendC::LocalTensor<dataType> &inLocal,
281	        AscendC::LocalTensor<float> &fp32Local,
282	        AscendC::LocalTensor<float> &tileLocal,
283	        AscendC::LocalTensor<uint8_t> &bcastTmpLocal)
284	    {
285	        inLocal = buf1D.Get<dataType>();
286	        LoadGmToUb(inLocal, gmSrc, static_cast<uint32_t>(N));
287	        AscendC::PipeBarrier<PIPE_MTE2>();
288	        AscendC::PipeBarrier<PIPE_ALL>();
289	        CastInputToFloat<dataType>(fp32Local, inLocal, castBuf, N);
290	        tileLocal = bufTile.Get<float>();
291	        bcastTmpLocal = bufBcastTmp.Get<uint8_t>();
292	        AscendC::PipeBarrier<PIPE_ALL>();
293	        const uint32_t srcShape[2] = {1U, static_cast<uint32_t>(N)};
294	        const uint32_t dstShape[2] = {
295	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
296	        AscendC::Broadcast<float, 2, 0>(tileLocal, fp32Local, dstShape, srcShape, bcastTmpLocal);
297	        AscendC::PipeBarrier<PIPE_V>();
298	    }
299	
300	    __aicore__ inline void ComputeDynamicQuant(
301	        AscendC::LocalTensor<float> &yFp32,
302	        AscendC::LocalTensor<float> &smoothTileFp32,
303	        AscendC::LocalTensor<float> &tempA,
304	        AscendC::LocalTensor<float> &tempB,
305	        AscendC::LocalTensor<float> &tempC,
306	        AscendC::LocalTensor<float> &outScale,
307	        AscendC::LocalTensor<int8_t> &outInt8,
308	        AscendC::LocalTensor<uint8_t> &reduceTmp,
309	        AscendC::LocalTensor<uint8_t> &bcastTmp,
310	        AscendC::LocalTensor<float> &maxAbsBuf,
311	        AscendC::LocalTensor<half> &quantHalf,
312	        int32_t tileSize)
313	    {
314	        const uint32_t reduceShape[2] = {
315	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
316	        const uint32_t scaleSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
317	        const uint32_t scaleDstShape[2] = {
318	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
319	
320	        // smooth_x = y * smooth
321	        AscendC::Mul(tempA, yFp32, smoothTileFp32, tileSize);
322	
323	        // max_abs = reduce_max(|smooth_x|)
324	        AscendC::Abs(tempB, tempA, tileSize);
325	        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::AR, false>(
326	            maxAbsBuf, tempB, reduceTmp, reduceShape, true);
327	
328	        // scale = max(max_abs, 1e-8) * inv127
329	        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, kMergeRowFactor);
330	        AscendC::Muls(outScale, maxAbsBuf, inv127, kMergeRowFactor);
331	
332	        // q = clamp(round(smooth_x / scale), -128, 127)
333	        AscendC::Broadcast<float, 2, 1>(tempC, outScale, scaleDstShape, scaleSrcShape, bcastTmp);
334	        AscendC::Div(tempA, tempA, tempC, tileSize);
335	        AscendC::Maxs(tempA, tempA, -128.0f, tileSize);
336	        AscendC::Mins(tempA, tempA, 127.0f, tileSize);
337	        // Cast: float -> half -> int8 (float->int8 not directly supported)
338	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, tileSize);
339	        AscendC::PipeBarrier<PIPE_V>();
340	        AscendC::Cast(outInt8, quantHalf, AscendC::RoundMode::CAST_RINT, tileSize);
341	    }
342	
343	    __aicore__ inline void ComputeRows(int32_t tileSize)
344	    {
345	        y1OutLocal_ = y1OutQueue_.AllocTensor<int8_t>();
346	        y2OutLocal_ = y2OutQueue_.AllocTensor<int8_t>();
347	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
348	        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
349	        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();
350	
351	        // Get temp buffers
352	        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
353	        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
354	        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
355	        AscendC::LocalTensor<float> xAddFp32 = xAddFp32Buf_.Get<float>();
356	        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
357	        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
358	        AscendC::LocalTensor<float> scaleBuf = scaleBuf_.Get<float>();
359	        AscendC::LocalTensor<float> maxAbsBuf = maxAbsBuf_.Get<float>();
360	        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
361	        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();
362	        AscendC::LocalTensor<uint8_t> bcastTmp = bcastTmpBuf_.Get<uint8_t>();
363	
364	        const uint32_t reduceShape[2] = {
365	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
366	        const uint32_t scaleSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
367	        const uint32_t scaleDstShape[2] = {
368	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
369	
370	        // DeQue x1, x2, cast to float32
371	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
372	        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, tileSize);
373	
374	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
375	        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, tileSize);
376	
377	        // ---- Add + RMSNorm ----
378	        // x_add = x1 + x2 (store in tempC, also save to xAddFp32)
379	        AscendC::Add(tempC, tempA, tempB, tileSize);
380	        AscendC::DataCopy(xAddFp32, tempC, tileSize);
381	
382	        // Write x_add to output (before RMSNorm modifies it)
383	        CastOutputBack<dataType>(xAddOutLocal_, xAddFp32, tileSize);
384	
385	        // x_add^2 → reuse tempA
386	        AscendC::Mul(tempA, tempC, tempC, tileSize);
387	
388	        // sum_sq = reduce_sum(x_add^2)
389	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
390	            sumBuf, tempA, reduceTmp, reduceShape, true);
391	
392	        // rstd = rsqrt(sum_sq * invN + eps)
393	        AscendC::Muls(rstdBuf, sumBuf, invN, kMergeRowFactor);
394	        AscendC::Adds(rstdBuf, rstdBuf, eps, kMergeRowFactor);
395	        AscendC::Rsqrt(rstdBuf, rstdBuf, kMergeRowFactor);
396	        AscendC::PipeBarrier<PIPE_V>();
397	
398	        // y = x_add * rstd * gamma (broadcast rstd)
399	        AscendC::Broadcast<float, 2, 1>(scaleBuf, rstdBuf, scaleDstShape, scaleSrcShape, bcastTmp);
400	        AscendC::Mul(tempC, xAddFp32, scaleBuf, tileSize);
401	        AscendC::Mul(tempC, tempC, gammaTileLocal_, tileSize);
402	
403	        // ---- DynamicQuant 1 ----
404	        // Preload smooth1
405	        AscendC::LocalTensor<dataType> smooth1InLocal;
406	        AscendC::LocalTensor<float> smooth1Fp32Local;
407	        AscendC::LocalTensor<float> smooth1TileLocal;
408	        AscendC::LocalTensor<uint8_t> smooth1BcastTmp;
409	        PreloadSmooth(smooth1GM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
410	            smooth1CastBuf_, smooth1InLocal, smooth1Fp32Local, smooth1TileLocal, smooth1BcastTmp);
411	
412	        // Reuse tempA, tempB, xAddFp32 for quant computation
413	        ComputeDynamicQuant(tempC, smooth1TileLocal, tempA, tempB, xAddFp32,
414	            scale1OutLocal_, y1OutLocal_, reduceTmp, bcastTmp, maxAbsBuf, quantHalf, tileSize);
415	
416	        // ---- DynamicQuant 2 ----
417	        AscendC::LocalTensor<dataType> smooth2InLocal;
418	        AscendC::LocalTensor<float> smooth2Fp32Local;
419	        AscendC::LocalTensor<float> smooth2TileLocal;
420	        AscendC::LocalTensor<uint8_t> smooth2BcastTmp;
421	        PreloadSmooth(smooth2GM_, smooth2_1DBuf_, smooth2TileBuf_, smooth2BcastTmpBuf_,
422	            smooth2CastBuf_, smooth2InLocal, smooth2Fp32Local, smooth2TileLocal, smooth2BcastTmp);
423	
424	        ComputeDynamicQuant(tempC, smooth2TileLocal, tempA, tempB, xAddFp32,
425	            scale2OutLocal_, y2OutLocal_, reduceTmp, bcastTmp, maxAbsBuf, quantHalf, tileSize);
426	
427	        // EnQue outputs
428	        x1InQueue_.FreeTensor(x1InLocal_);
429	        x2InQueue_.FreeTensor(x2InLocal_);
430	        y1OutQueue_.EnQue(y1OutLocal_);
431	        y2OutQueue_.EnQue(y2OutLocal_);
432	        xAddOutQueue_.EnQue(xAddOutLocal_);
433	        scale1OutQueue_.EnQue(scale1OutLocal_);
434	        scale2OutQueue_.EnQue(scale2OutLocal_);
435	    }
436	
437	    __aicore__ inline void ComputeSingleRow()
438	    {
439	        // Single row fallback: use same buffer footprint, process just one row
440	        y1OutLocal_ = y1OutQueue_.AllocTensor<int8_t>();
441	        y2OutLocal_ = y2OutQueue_.AllocTensor<int8_t>();
442	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
443	        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
444	        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();
445	
446	        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
447	        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
448	        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
449	        AscendC::LocalTensor<float> xAddFp32 = xAddFp32Buf_.Get<float>();
450	        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
451	        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
452	        AscendC::LocalTensor<float> maxAbsBuf = maxAbsBuf_.Get<float>();
453	        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
454	        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();
455	        AscendC::LocalTensor<uint8_t> bcastTmp = bcastTmpBuf_.Get<uint8_t>();
456	
457	        const uint32_t scaleSrcShape[2] = {1U, 1U};
458	        const uint32_t scaleDstShape[2] = {1U, static_cast<uint32_t>(N)};
459	        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(N)};
460	
461	        // DeQue x1, x2
462	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
463	        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, N);
464	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
465	        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, N);
466	
467	        // x_add = x1 + x2
468	        AscendC::Add(tempC, tempA, tempB, N);
469	        AscendC::DataCopy(xAddFp32, tempC, N);
470	        CastOutputBack<dataType>(xAddOutLocal_, xAddFp32, N);
471	
472	        // sum_sq
473	        AscendC::Mul(tempA, tempC, tempC, N);
474	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::RA, false>(
475	            sumBuf, tempA, reduceTmp, reduceShape, true);
476	        float meanSq = sumBuf.GetValue(0) * invN + eps;
477	        AscendC::Duplicate(sumBuf, meanSq, 1);
478	        AscendC::Rsqrt(rstdBuf, sumBuf, 1);
479	        AscendC::PipeBarrier<PIPE_ALL>();
480	        float invRmsVal = rstdBuf.GetValue(0);
481	        AscendC::PipeBarrier<PIPE_ALL>();
482	
483	        // y = x_add * rstd * gamma
484	        AscendC::Muls(tempC, xAddFp32, invRmsVal, N);
485	        AscendC::Mul(tempC, tempC, gammaTileLocal_, N);
486	
487	        // DynamicQuant 1
488	        AscendC::LocalTensor<dataType> smooth1InLocal;
489	        AscendC::LocalTensor<float> smooth1Fp32Local;
490	        AscendC::LocalTensor<float> smooth1TileLocal;
491	        AscendC::LocalTensor<uint8_t> smooth1BcastTmp;
492	        PreloadSmooth(smooth1GM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
493	            smooth1CastBuf_, smooth1InLocal, smooth1Fp32Local, smooth1TileLocal, smooth1BcastTmp);
494	
495	        AscendC::Mul(tempA, tempC, smooth1TileLocal, N);
496	        AscendC::Abs(tempB, tempA, N);
497	        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::RA, false>(
498	            maxAbsBuf, tempB, reduceTmp, reduceShape, true);
499	        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, 1);
500	        AscendC::PipeBarrier<PIPE_V>();
501	        AscendC::Muls(scale1OutLocal_, maxAbsBuf, inv127, 1);
502	
503	        AscendC::Broadcast<float, 2, 1>(tempB, scale1OutLocal_, scaleDstShape, scaleSrcShape, bcastTmp);
504	        AscendC::Div(tempA, tempA, tempB, N);
505	        AscendC::Maxs(tempA, tempA, -128.0f, N);
506	        AscendC::Mins(tempA, tempA, 127.0f, N);
507	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
508	        AscendC::PipeBarrier<PIPE_V>();
509	        AscendC::Cast(y1OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);
510	
511	        // DynamicQuant 2
512	        AscendC::LocalTensor<dataType> smooth2InLocal;
513	        AscendC::LocalTensor<float> smooth2Fp32Local;
514	        AscendC::LocalTensor<float> smooth2TileLocal;
515	        AscendC::LocalTensor<uint8_t> smooth2BcastTmp;
516	        PreloadSmooth(smooth2GM_, smooth2_1DBuf_, smooth2TileBuf_, smooth2BcastTmpBuf_,
517	            smooth2CastBuf_, smooth2InLocal, smooth2Fp32Local, smooth2TileLocal, smooth2BcastTmp);
518	
519	        AscendC::Mul(tempA, tempC, smooth2TileLocal, N);
520	        AscendC::Abs(tempB, tempA, N);
521	        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::RA, false>(
522	            maxAbsBuf, tempB, reduceTmp, reduceShape, true);
523	        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, 1);
524	        AscendC::Muls(scale2OutLocal_, maxAbsBuf, inv127, 1);
525	
526	        AscendC::Broadcast<float, 2, 1>(tempB, scale2OutLocal_, scaleDstShape, scaleSrcShape, bcastTmp);
527	        AscendC::Div(tempA, tempA, tempB, N);
528	        AscendC::Maxs(tempA, tempA, -128.0f, N);
529	        AscendC::Mins(tempA, tempA, 127.0f, N);
530	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
531	        AscendC::PipeBarrier<PIPE_V>();
532	        AscendC::Cast(y2OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);
533	
534	        x1InQueue_.FreeTensor(x1InLocal_);
535	        x2InQueue_.FreeTensor(x2InLocal_);
536	        y1OutQueue_.EnQue(y1OutLocal_);
537	        y2OutQueue_.EnQue(y2OutLocal_);
538	        xAddOutQueue_.EnQue(xAddOutLocal_);
539	        scale1OutQueue_.EnQue(scale1OutLocal_);
540	        scale2OutQueue_.EnQue(scale2OutLocal_);
541	    }
542	
543	    __aicore__ inline void ProcessSingleRow(int32_t rowIdx)
544	    {
545	        CopyInX1(rowIdx, N);
546	        CopyInX2(rowIdx, N);
547	        ComputeSingleRow();
548	        CopyOutY1(rowIdx, N);
549	        CopyOutY2(rowIdx, N);
550	        CopyOutXAdd(rowIdx, N);
551	        CopyOutScale1(rowIdx, 1);
552	        CopyOutScale2(rowIdx, 1);
553	    }
554	
555	    __aicore__ inline void ProcessRows(int32_t rowBase, int32_t validRows)
556	    {
557	        if (validRows < kMergeRowFactor) {
558	            for (int r = 0; r < validRows; ++r) {
559	                ProcessSingleRow(rowBase + r);
560	            }
561	            return;
562	        }
563	        const int32_t tileSize = kMergeRowFactor * N;
564	        CopyInX1(rowBase, tileSize);
565	        CopyInX2(rowBase, tileSize);
566	        ComputeRows(tileSize);
567	        CopyOutY1(rowBase, tileSize);
568	        CopyOutY2(rowBase, tileSize);
569	        CopyOutXAdd(rowBase, tileSize);
570	        CopyOutScale1(rowBase, kMergeRowFactor);
571	        CopyOutScale2(rowBase, kMergeRowFactor);
572	    }
