657	// =========================================================================
658	// Strategy 2: single_row — N > 1024, one row at a time
659	// =========================================================================
660	
661	template <typename dataType>
662	class AddRmsNormDynamicQuantSingleRowKernel {
663	public:
664	    __aicore__ inline void Init(
665	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma,
666	        GM_ADDR smooth1, GM_ADDR smooth2,
667	        GM_ADDR y1, GM_ADDR y2, GM_ADDR x_add_out,
668	        GM_ADDR scale1, GM_ADDR scale2,
669	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
670	        int32_t tasksPerCore, float eps, float invN,
671	        float inv127)
672	    {
673	        this->M = M;
674	        this->N = N;
675	        this->blockM = blockM;
676	        this->usedCoreNum = usedCoreNum;
677	        this->tasksPerCore = tasksPerCore;
678	        this->eps = eps;
679	        this->invN = invN;
680	        this->inv127 = inv127;
681	
682	        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
683	        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
684	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
685	        smooth1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth1), N);
686	        smooth2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth2), N);
687	        y1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y1), static_cast<uint64_t>(M) * N);
688	        y2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y2), static_cast<uint64_t>(M) * N);
689	        xAddGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_add_out), static_cast<uint64_t>(M) * N);
690	        scale1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale1), M);
691	        scale2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale2), M);
692	
693	        if ASCEND_IS_AIV {
694	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
695	
696	            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
697	            pipe.InitBuffer(smooth1Buf_, N * sizeof(dataType));
698	            pipe.InitBuffer(smooth2Buf_, N * sizeof(dataType));
699	            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N * sizeof(dataType));
700	            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N * sizeof(dataType));
701	            pipe.InitBuffer(y1OutQueue_, BUFFER_NUM, N * sizeof(int8_t));
702	            pipe.InitBuffer(y2OutQueue_, BUFFER_NUM, N * sizeof(int8_t));
703	            pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, N * sizeof(dataType));
704	            pipe.InitBuffer(scale1OutQueue_, BUFFER_NUM, sizeof(float));
705	            pipe.InitBuffer(scale2OutQueue_, BUFFER_NUM, sizeof(float));
706	
707	            pipe.InitBuffer(tempBufA_, N * sizeof(float));
708	            pipe.InitBuffer(tempBufB_, N * sizeof(float));
709	            pipe.InitBuffer(tempBufC_, N * sizeof(float));
710	            pipe.InitBuffer(quantHalfBuf_, N * sizeof(half));
711	            pipe.InitBuffer(reduceTmpBuf_, 2 * N * sizeof(float));
712	            pipe.InitBuffer(bcastTmpBuf_, 2 * N * sizeof(uint8_t));
713	            pipe.InitBuffer(sumBuf_, sizeof(float));
714	            pipe.InitBuffer(rstdBuf_, sizeof(float));
715	
716	            if constexpr (!std::is_same_v<dataType, float>) {
717	                pipe.InitBuffer(x1CastBuf_, N * sizeof(float));
718	                pipe.InitBuffer(x2CastBuf_, N * sizeof(float));
719	                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
720	                pipe.InitBuffer(smooth1CastBuf_, N * sizeof(float));
721	                pipe.InitBuffer(smooth2CastBuf_, N * sizeof(float));
722	                pipe.InitBuffer(xAddCastBuf_, N * sizeof(float));
723	            }
724	
725	            // Pre-load gamma, smooth1, smooth2
726	            gammaInLocal_ = gammaBuf_.Get<dataType>();
727	            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
728	            CastInputToFloat<dataType>(gammaFp32Local_, gammaInLocal_, gammaCastBuf_, N);
729	
730	            smooth1InLocal_ = smooth1Buf_.Get<dataType>();
731	            LoadGmToUb(smooth1InLocal_, smooth1GM_, static_cast<uint32_t>(N));
732	            CastInputToFloat<dataType>(smooth1Fp32Local_, smooth1InLocal_, smooth1CastBuf_, N);
733	
734	            smooth2InLocal_ = smooth2Buf_.Get<dataType>();
735	            LoadGmToUb(smooth2InLocal_, smooth2GM_, static_cast<uint32_t>(N));
736	            CastInputToFloat<dataType>(smooth2Fp32Local_, smooth2InLocal_, smooth2CastBuf_, N);
737	        }
738	    }
739	
740	    __aicore__ inline void Process()
741	    {
742	        if ASCEND_IS_AIV {
743	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
744	            const int subBlockIdx = AscendC::GetSubBlockIdx();
745	            const int mNum = (M + blockM - 1) / blockM;
746	
747	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
748	                const int bx = coreIdx * tasksPerCore + localIdx;
749	                if (bx >= mNum) { continue; }
750	                for (int row = 0; row < subBlockRows_; ++row) {
751	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
752	                    if (rowIdx < M) { ProcessRow(rowIdx); }
753	                }
754	            }
755	        }
756	    }
757	
758	private:
