760	    {
761	        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
762	        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
763	        x1InQueue_.EnQue(x1InLocal_);
764	    }
