787	    __aicore__ inline void CopyOutXAdd(int32_t rowIdx)
788	    {
789	        xAddOutLocal_ = xAddOutQueue_.DeQue<dataType>();
790	        StoreUbToGm(xAddGM_[static_cast<uint64_t>(rowIdx) * N], xAddOutLocal_, static_cast<uint32_t>(N));
791	        xAddOutQueue_.FreeTensor(xAddOutLocal_);
792	    }
