794	    __aicore__ inline void CopyOutScale1(int32_t rowIdx)
795	    {
796	        scale1OutLocal_ = scale1OutQueue_.DeQue<float>();
797	        StoreUbToGm(scale1GM_[rowIdx], scale1OutLocal_, 1);
798	        scale1OutQueue_.FreeTensor(scale1OutLocal_);
799	    }
800	
801	    __aicore__ inline void CopyOutScale2(int32_t rowIdx)
802	    {
803	        scale2OutLocal_ = scale2OutQueue_.DeQue<float>();
804	        StoreUbToGm(scale2GM_[rowIdx], scale2OutLocal_, 1);
805	        scale2OutQueue_.FreeTensor(scale2OutLocal_);
806	    }
807	
808	    __aicore__ inline void ComputeRow()
809	    {
810	        y1OutLocal_ = y1OutQueue_.AllocTensor<int8_t>();
811	        y2OutLocal_ = y2OutQueue_.AllocTensor<int8_t>();
812	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
813	        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
814	        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();
815	
816	        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
817	        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
818	        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
819	        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
820	        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
821	        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
822	        AscendC::LocalTensor<float> reduceTmp = reduceTmpBuf_.Get<float>();
823	        AscendC::LocalTensor<uint8_t> bcastTmp = bcastTmpBuf_.Get<uint8_t>();
824	
825	        // DeQue x1, x2
826	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
827	        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, N);
828	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
829	        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, N);
830	
831	        // ---- Add + RMSNorm ----
832	        // x_add = x1 + x2 → tempC
833	        AscendC::Add(tempC, tempA, tempB, N);
834	
835	        // Save x_add → xAddOutLocal_ before RMSNorm modifies tempC
836	        CastOutputBack<dataType>(xAddOutLocal_, tempC, N);
837	
838	        // x_add^2 → tempA
839	        AscendC::Mul(tempA, tempC, tempC, N);
840	        AscendC::ReduceSum<float>(sumBuf, tempA, reduceTmp, N);
841	
842	        float meanSq = sumBuf.GetValue(0) * invN + eps;
843	        AscendC::Duplicate(sumBuf, meanSq, 1);
844	        AscendC::Rsqrt(rstdBuf, sumBuf, 1);
845	        AscendC::PipeBarrier<PIPE_ALL>();
846	        float invRmsVal = rstdBuf.GetValue(0);
847	        AscendC::PipeBarrier<PIPE_ALL>();
848	
849	        // y = x_add * rstd * gamma
850	        AscendC::Muls(tempC, tempC, invRmsVal, N);
851	        AscendC::Mul(tempC, tempC, gammaFp32Local_, N);
852	
853	        // ---- DynamicQuant 1 ----
854	        // smooth_x1 = y * smooth1
855	        AscendC::Mul(tempA, tempC, smooth1Fp32Local_, N);
856	        // max_abs1 = max(|smooth_x1|)
857	        AscendC::Abs(tempB, tempA, N);
858	        AscendC::ReduceMax<float>(sumBuf, tempB, reduceTmp, N);
859	        AscendC::PipeBarrier<PIPE_ALL>();
860	        float maxAbs1 = sumBuf.GetValue(0);
861	        maxAbs1 = (maxAbs1 > 1e-8f) ? maxAbs1 : 1e-8f;
862	
863	        // scale1 = max_abs1 * inv127
864	        float scale1Val = maxAbs1 * inv127;
865	        AscendC::Duplicate(scale1OutLocal_, scale1Val, 1);
866	
867	        // q1 = clamp(round(smooth_x1 / scale1), -128, 127)
868	        AscendC::Muls(tempA, tempA, 1.0f / scale1Val, N);
869	        AscendC::Maxs(tempA, tempA, -128.0f, N);
870	        AscendC::Mins(tempA, tempA, 127.0f, N);
871	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
872	        AscendC::PipeBarrier<PIPE_V>();
873	        AscendC::Cast(y1OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);
874	
875	        // ---- DynamicQuant 2 ----
876	        AscendC::Mul(tempA, tempC, smooth2Fp32Local_, N);
877	        AscendC::Abs(tempB, tempA, N);
878	        AscendC::ReduceMax<float>(sumBuf, tempB, reduceTmp, N);
879	        AscendC::PipeBarrier<PIPE_ALL>();
880	        float maxAbs2 = sumBuf.GetValue(0);
881	        maxAbs2 = (maxAbs2 > 1e-8f) ? maxAbs2 : 1e-8f;
882	
883	        float scale2Val = maxAbs2 * inv127;
884	        AscendC::Duplicate(scale2OutLocal_, scale2Val, 1);
885	
886	        AscendC::Muls(tempA, tempA, 1.0f / scale2Val, N);
887	        AscendC::Maxs(tempA, tempA, -128.0f, N);
888	        AscendC::Mins(tempA, tempA, 127.0f, N);
889	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
890	        AscendC::PipeBarrier<PIPE_V>();
891	        AscendC::Cast(y2OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);
892	
893	        x1InQueue_.FreeTensor(x1InLocal_);
894	        x2InQueue_.FreeTensor(x2InLocal_);
895	        y1OutQueue_.EnQue(y1OutLocal_);
896	        y2OutQueue_.EnQue(y2OutLocal_);
897	        xAddOutQueue_.EnQue(xAddOutLocal_);
898	        scale1OutQueue_.EnQue(scale1OutLocal_);
899	        scale2OutQueue_.EnQue(scale2OutLocal_);
900	    }
