32	std::vector<at::Tensor> add_rms_norm_dynamic_quant(
33	    const at::Tensor &x1, const at::Tensor &x2,
34	    const at::Tensor &gamma, double eps,
35	    const at::Tensor &smooth1, const at::Tensor &smooth2)
36	{
37	    TORCH_CHECK(x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
38	                   x1.scalar_type() == at::kBFloat16,
39	        "x1 must be float16, float32, or bfloat16");
40	    TORCH_CHECK(x1.scalar_type() == x2.scalar_type(),
41	        "x1 and x2 must have the same dtype");
42	    TORCH_CHECK(gamma.scalar_type() == x1.scalar_type(),
43	        "gamma must have the same dtype as x1/x2");
44	    TORCH_CHECK(smooth1.scalar_type() == x1.scalar_type(),
45	        "smooth1 must have the same dtype as x1/x2");
46	    TORCH_CHECK(smooth2.scalar_type() == x1.scalar_type(),
47	        "smooth2 must have the same dtype as x1/x2");
48	    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [N]");
49	    TORCH_CHECK(x1.sizes().back() == gamma.sizes()[0],
50	        "gamma shape mismatch");
51	    TORCH_CHECK(x1.sizes() == x2.sizes(), "x1 and x2 must have the same shape");
52	
53	    auto origShape = x1.sizes();
54	    int32_t N = static_cast<int32_t>(x1.sizes().back());
55	    int64_t M = x1.numel() / N;
56	
57	    at::Tensor x1_2d = x1.contiguous().view({M, N});
58	    at::Tensor x2_2d = x2.contiguous().view({M, N});
59	
60	    int32_t M_i32 = static_cast<int32_t>(M);
61	    int32_t mNum = (M_i32 + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
62	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
63	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
64	
65	    // Output tensors
66	    at::Tensor y1 = at::empty({M, N}, x1_2d.options().dtype(at::kChar));  // int8
67	    at::Tensor y2 = at::empty({M, N}, x1_2d.options().dtype(at::kChar));  // int8
68	    at::Tensor x_add = at::empty_like(x1_2d);
69	    at::Tensor scale1 = at::empty({static_cast<int64_t>(M)}, at::TensorOptions().dtype(at::kFloat).device(x1.device()));
70	    at::Tensor scale2 = at::empty({static_cast<int64_t>(M)}, at::TensorOptions().dtype(at::kFloat).device(x1.device()));
71	
72	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
73	    int64_t dtypeFlag = 0;
74	    if (x1_2d.scalar_type() == at::kHalf) {
75	        dtypeFlag = 1;
76	    } else if (x1_2d.scalar_type() == at::kBFloat16) {
77	        dtypeFlag = 2;
78	    }
79	
80	    // Left-value params for EXEC_KERNEL_CMD
81	    int32_t blockM = DEFAULT_BLOCK_M;
82	    int32_t rowFactor = DEFAULT_ROW_FACTOR;
83	    float epsVal = static_cast<float>(eps);
84	    float invN = 1.0f / static_cast<float>(N);
85	    float inv127 = 1.0f / 127.0f;
86	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
87	
88	    // Strategy dispatch based on N
89	    if (N <= 1024) {
90	        EXEC_KERNEL_CMD(add_rms_norm_dynamic_quant_merge_n, blockDim,
91	                        x1_2d, x2_2d, gamma, smooth1, smooth2,
92	                        y1, y2, x_add, scale1, scale2,
93	                        M_i32, N, blockM, usedCoreNum,
94	                        tasksPerCore, rowFactor, epsVal, invN, inv127, dtypeFlag);
95	    } else {
96	        EXEC_KERNEL_CMD(add_rms_norm_dynamic_quant_single_row, blockDim,
97	                        x1_2d, x2_2d, gamma, smooth1, smooth2,
98	                        y1, y2, x_add, scale1, scale2,
99	                        M_i32, N, blockM, usedCoreNum,
100	                        tasksPerCore, epsVal, invN, inv127, dtypeFlag);
101	    }
102	
103	    return {y1, y2, x_add, scale1, scale2};
104	}
