    __aicore__ inline void PreloadSmooth(
        AscendC::GlobalTensor<dataType> &gmSrc,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf1D,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &bufTile,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &bufBcastTmp,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
        AscendC::LocalTensor<dataType> &inLocal,
        AscendC::LocalTensor<float> &fp32Local,
        AscendC::LocalTensor<float> &tileLocal,
        AscendC::LocalTensor<uint8_t> &bcastTmpLocal)
    {
        inLocal = buf1D.Get<dataType>();
