    __aicore__ inline void ComputeDynamicQuant(
        AscendC::LocalTensor<float> &yFp32,
        AscendC::LocalTensor<float> &smoothTileFp32,
        AscendC::LocalTensor<float> &tempA,
        AscendC::LocalTensor<float> &tempB,
        AscendC::LocalTensor<float> &tempC,
        AscendC::LocalTensor<float> &outScale,
        AscendC::LocalTensor<int8_t> &outInt8,
        AscendC::LocalTensor<float> &reduceTmp,
        AscendC::LocalTensor<uint8_t> &bcastTmp,
        AscendC::LocalTensor<float> &maxAbsBuf,
        AscendC::LocalTensor<half> &quantHalf,
        int32_t tileSize)
    {
        const uint32_t reduceShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
        const uint32_t scaleSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
        const uint32_t scaleDstShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};

        // smooth_x = y * smooth
        AscendC::Mul(tempA, yFp32, smoothTileFp32, tileSize);

        // max_abs = reduce_max(|smooth_x|)
        AscendC::Abs(tempB, tempA, tileSize);
        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::AR, false>(
            maxAbsBuf, tempB, reduceTmp, reduceShape, true);

        // scale = max(max_abs, 1e-8) * inv127
        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, kMergeRowFactor);
        AscendC::Muls(outScale, maxAbsBuf, inv127, kMergeRowFactor);

        // q = clamp(round(smooth_x / scale), -128, 127)
        AscendC::Broadcast<float, 2, 1>(tempC, outScale, scaleDstShape, scaleSrcShape, bcastTmp);
        AscendC::Div(tempA, tempA, tempC, tileSize);
        AscendC::Maxs(tempA, tempA, -128.0f, tileSize);
        AscendC::Mins(tempA, tempA, 127.0f, tileSize);
        // Cast: float -> half -> int8 (float->int8 not directly supported)
        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, tileSize);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(outInt8, quantHalf, AscendC::RoundMode::CAST_RINT, tileSize);
    }

    __aicore__ inline void ComputeRows(int32_t tileSize)
    {
        gq1OutLocal_ = gq1OutQueue_.AllocTensor<int8_t>();
        gq2OutLocal_ = gq2OutQueue_.AllocTensor<int8_t>();
        y3OutLocal_ = y3OutQueue_.AllocTensor<float>();
        y4OutLocal_ = y4OutQueue_.AllocTensor<dataType>();
        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();

        // Get temp buffers
        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
        AscendC::LocalTensor<float> xAddFp32 = xAddFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> yNormFp32 = yNormFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
        AscendC::LocalTensor<float> scaleBuf = scaleBuf_.Get<float>();
        AscendC::LocalTensor<float> maxAbsBuf = maxAbsBuf_.Get<float>();
        AscendC::LocalTensor<float> reduceTmp = reduceTmpBuf_.Get<float>();
        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
        AscendC::LocalTensor<uint8_t> bcastTmp = bcastTmpBuf_.Get<uint8_t>();

        const uint32_t reduceShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
        const uint32_t scaleSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
        const uint32_t scaleDstShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};

        // DeQue x1, x2, cast to float32
        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, tileSize);

        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, tileSize);

        // ---- Add + RMSNorm ----
        // x_add = x1 + x2
        AscendC::Add(tempC, tempA, tempB, tileSize);
        AscendC::DataCopy(xAddFp32, tempC, tileSize);

        // Write x_add to output (orig dtype)
        CastOutputBack<dataType>(xAddOutLocal_, xAddFp32, tileSize);

        // x_add^2 → reuse tempA
        AscendC::Mul(tempA, tempC, tempC, tileSize);

        // sum_sq = reduce_sum(x_add^2)
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumBuf, tempA, reduceTmp, reduceShape, true);

        // rstd = rsqrt(sum_sq * invN + eps)
        AscendC::Muls(rstdBuf, sumBuf, invN, kMergeRowFactor);
        AscendC::Adds(rstdBuf, rstdBuf, eps, kMergeRowFactor);
        AscendC::Rsqrt(rstdBuf, rstdBuf, kMergeRowFactor);
        AscendC::PipeBarrier<PIPE_V>();

        // y = x_add * rstd * gamma + beta  (RMSNorm with bias)
        AscendC::Broadcast<float, 2, 1>(scaleBuf, rstdBuf, scaleDstShape, scaleSrcShape, bcastTmp);
        AscendC::Mul(tempC, xAddFp32, scaleBuf, tileSize);
        AscendC::Mul(tempC, tempC, gammaTileLocal_, tileSize);
        AscendC::Add(tempC, tempC, betaTileLocal_, tileSize);

        // Save RMSNorm output y to yNormFp32
        AscendC::DataCopy(yNormFp32, tempC, tileSize);

        // Write y3_out (FP32 RMSNorm output)
        AscendC::DataCopy(y3OutLocal_, yNormFp32, tileSize);

        // Write y4_out (orig dtype RMSNorm output)
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(y4OutLocal_, yNormFp32, tileSize);
        } else {
            CastOutputBack<dataType>(y4OutLocal_, yNormFp32, tileSize);
        }

        // ---- DynamicQuant 1 ----
        AscendC::LocalTensor<dataType> smooth1InLocal;
        AscendC::LocalTensor<float> smooth1Fp32Local;
        AscendC::LocalTensor<float> smooth1TileLocal;
        AscendC::LocalTensor<uint8_t> smooth1BcastTmp;
        PreloadSmooth(smooth1GM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
            smooth1CastBuf_, smooth1InLocal, smooth1Fp32Local, smooth1TileLocal, smooth1BcastTmp);

        ComputeDynamicQuant(yNormFp32, smooth1TileLocal, tempA, tempB, xAddFp32,
            scale1OutLocal_, gq1OutLocal_, reduceTmp, bcastTmp, maxAbsBuf, quantHalf, tileSize);

        // ---- DynamicQuant 2 ----
        AscendC::LocalTensor<dataType> smooth2InLocal;
        AscendC::LocalTensor<float> smooth2Fp32Local;
        AscendC::LocalTensor<float> smooth2TileLocal;
        AscendC::LocalTensor<uint8_t> smooth2BcastTmp;
        PreloadSmooth(smooth2GM_, smooth2_1DBuf_, smooth2TileBuf_, smooth2BcastTmpBuf_,
            smooth2CastBuf_, smooth2InLocal, smooth2Fp32Local, smooth2TileLocal, smooth2BcastTmp);

        ComputeDynamicQuant(yNormFp32, smooth2TileLocal, tempA, tempB, xAddFp32,
            scale2OutLocal_, gq2OutLocal_, reduceTmp, bcastTmp, maxAbsBuf, quantHalf, tileSize);

        // EnQue outputs
        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        gq1OutQueue_.EnQue(gq1OutLocal_);
        gq2OutQueue_.EnQue(gq2OutLocal_);
        y3OutQueue_.EnQue(y3OutLocal_);
        y4OutQueue_.EnQue(y4OutLocal_);
        xAddOutQueue_.EnQue(xAddOutLocal_);
        scale1OutQueue_.EnQue(scale1OutLocal_);
        scale2OutQueue_.EnQue(scale2OutLocal_);
    }

    __aicore__ inline void ComputeSingleRow()
    {
        gq1OutLocal_ = gq1OutQueue_.AllocTensor<int8_t>();
        gq2OutLocal_ = gq2OutQueue_.AllocTensor<int8_t>();
        y3OutLocal_ = y3OutQueue_.AllocTensor<float>();
        y4OutLocal_ = y4OutQueue_.AllocTensor<dataType>();
        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();

        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
        AscendC::LocalTensor<float> xAddFp32 = xAddFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> yNormFp32 = yNormFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
        AscendC::LocalTensor<float> maxAbsBuf = maxAbsBuf_.Get<float>();
        AscendC::LocalTensor<float> reduceTmp = reduceTmpBuf_.Get<float>();
        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
        AscendC::LocalTensor<uint8_t> bcastTmp = bcastTmpBuf_.Get<uint8_t>();

        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(N)};

        // DeQue x1, x2
        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, N);
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, N);

        // x_add = x1 + x2
        AscendC::Add(tempC, tempA, tempB, N);
        AscendC::DataCopy(xAddFp32, tempC, N);
        CastOutputBack<dataType>(xAddOutLocal_, xAddFp32, N);

        // sum_sq
        AscendC::Mul(tempA, tempC, tempC, N);
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::RA, false>(
            sumBuf, tempA, reduceTmp, reduceShape, true);
        float meanSq = sumBuf.GetValue(0) * invN + eps;
        AscendC::Duplicate(sumBuf, meanSq, 1);
        AscendC::Rsqrt(rstdBuf, sumBuf, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        float invRmsVal = rstdBuf.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // y = x_add * rstd * gamma + beta (RMSNorm with bias)
        AscendC::Muls(tempC, xAddFp32, invRmsVal, N);
        AscendC::Mul(tempC, tempC, gammaTileLocal_, N);
        AscendC::Add(tempC, tempC, betaTileLocal_, N);

        // Save RMSNorm output y
        AscendC::DataCopy(yNormFp32, tempC, N);

        // Write y3_out (FP32)
        AscendC::DataCopy(y3OutLocal_, yNormFp32, N);

        // Write y4_out (orig dtype)
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(y4OutLocal_, yNormFp32, N);
        } else {
            CastOutputBack<dataType>(y4OutLocal_, yNormFp32, N);
        }

        // DynamicQuant 1
        AscendC::LocalTensor<dataType> smooth1InLocal;
        AscendC::LocalTensor<float> smooth1Fp32Local;
        AscendC::LocalTensor<float> smooth1TileLocal;
        AscendC::LocalTensor<uint8_t> smooth1BcastTmp;
        PreloadSmooth(smooth1GM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
            smooth1CastBuf_, smooth1InLocal, smooth1Fp32Local, smooth1TileLocal, smooth1BcastTmp);

        AscendC::Mul(tempA, yNormFp32, smooth1TileLocal, N);
        AscendC::Abs(tempB, tempA, N);
        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::RA, false>(
            maxAbsBuf, tempB, reduceTmp, reduceShape, true);
        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, 1);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(scale1OutLocal_, maxAbsBuf, inv127, 1);

        const uint32_t scaleSrcShape_1[2] = {1U, 1U};
        const uint32_t scaleDstShape_1[2] = {1U, static_cast<uint32_t>(N)};
        AscendC::Broadcast<float, 2, 1>(tempB, scale1OutLocal_, scaleDstShape_1, scaleSrcShape_1, bcastTmp);
        AscendC::Div(tempA, tempA, tempB, N);
        AscendC::Maxs(tempA, tempA, -128.0f, N);
        AscendC::Mins(tempA, tempA, 127.0f, N);
        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(gq1OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);

        // DynamicQuant 2
        AscendC::LocalTensor<dataType> smooth2InLocal;
        AscendC::LocalTensor<float> smooth2Fp32Local;
        AscendC::LocalTensor<float> smooth2TileLocal;
        AscendC::LocalTensor<uint8_t> smooth2BcastTmp;
        PreloadSmooth(smooth2GM_, smooth2_1DBuf_, smooth2TileBuf_, smooth2BcastTmpBuf_,
            smooth2CastBuf_, smooth2InLocal, smooth2Fp32Local, smooth2TileLocal, smooth2BcastTmp);

        AscendC::Mul(tempA, yNormFp32, smooth2TileLocal, N);
        AscendC::Abs(tempB, tempA, N);
        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::RA, false>(
            maxAbsBuf, tempB, reduceTmp, reduceShape, true);
        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, 1);
        AscendC::Muls(scale2OutLocal_, maxAbsBuf, inv127, 1);

        AscendC::Broadcast<float, 2, 1>(tempB, scale2OutLocal_, scaleDstShape_1, scaleSrcShape_1, bcastTmp);
        AscendC::Div(tempA, tempA, tempB, N);
        AscendC::Maxs(tempA, tempA, -128.0f, N);
        AscendC::Mins(tempA, tempA, 127.0f, N);
        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(gq2OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        gq1OutQueue_.EnQue(gq1OutLocal_);
        gq2OutQueue_.EnQue(gq2OutLocal_);
        y3OutQueue_.EnQue(y3OutLocal_);
        y4OutQueue_.EnQue(y4OutLocal_);
        xAddOutQueue_.EnQue(xAddOutLocal_);
        scale1OutQueue_.EnQue(scale1OutLocal_);
        scale2OutQueue_.EnQue(scale2OutLocal_);
    }

    __aicore__ inline void ProcessSingleRow(int32_t rowIdx)
    {
        CopyInX1(rowIdx, N);
        CopyInX2(rowIdx, N);
        ComputeSingleRow();
        CopyOutGq1(rowIdx, N);
        CopyOutGq2(rowIdx, N);
        CopyOutY3Fp32(rowIdx, N);
        CopyOutY4Dtype(rowIdx, N);
        CopyOutXAdd(rowIdx, N);
        CopyOutScale1(rowIdx, 1);
        CopyOutScale2(rowIdx, 1);
    }

    __aicore__ inline void ProcessRows(int32_t rowBase, int32_t validRows)
    {
        if (validRows < kMergeRowFactor) {
            for (int r = 0; r < validRows; ++r) {
                ProcessSingleRow(rowBase + r);
            }
            return;
        }
        const int32_t tileSize = kMergeRowFactor * N;
        CopyInX1(rowBase, tileSize);
        CopyInX2(rowBase, tileSize);
        ComputeRows(tileSize);
        CopyOutGq1(rowBase, tileSize);
        CopyOutGq2(rowBase, tileSize);
        CopyOutY3Fp32(rowBase, tileSize);
        CopyOutY4Dtype(rowBase, tileSize);
        CopyOutXAdd(rowBase, tileSize);
        CopyOutScale1(rowBase, kMergeRowFactor);
        CopyOutScale2(rowBase, kMergeRowFactor);
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t rowFactor = 0;
    float eps = 0.0f;
    float invN = 0.0f;
    float inv127 = 0.0f;
    int32_t subBlockRows_ = 0;
    int32_t rowLoops_ = 0;

    AscendC::TPipe pipe;

    // GM tensors — inputs
    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<dataType> gammaGM_;
    AscendC::GlobalTensor<dataType> betaGM_;
    AscendC::GlobalTensor<dataType> smooth1GM_;
    AscendC::GlobalTensor<dataType> smooth2GM_;
    // GM tensors — outputs
    AscendC::GlobalTensor<int8_t> gq1GM_;
    AscendC::GlobalTensor<int8_t> gq2GM_;
    AscendC::GlobalTensor<float> y3Fp32GM_;
    AscendC::GlobalTensor<dataType> y4DtypeGM_;
    AscendC::GlobalTensor<dataType> xAddGM_;
    AscendC::GlobalTensor<float> scale1GM_;
    AscendC::GlobalTensor<float> scale2GM_;

    // Queues
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> gq1OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> gq2OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> y3OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> y4OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> xAddOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> scale1OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> scale2OutQueue_;

    // Pre-loaded buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> gamma1DBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> beta1DBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaBcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth1_1DBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth1TileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth1BcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth2_1DBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth2TileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth2BcastTmpBuf_;

    // Compute buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufA_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufB_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufC_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xAddFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yNormFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> quantHalfBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rstdBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxAbsBuf_;

    // Cast buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xAddCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> y4CastBuf_;

    // Locals
    AscendC::LocalTensor<dataType> x1InLocal_;
    AscendC::LocalTensor<dataType> x2InLocal_;
    AscendC::LocalTensor<dataType> gammaInLocal_;
    AscendC::LocalTensor<dataType> betaInLocal_;
    AscendC::LocalTensor<int8_t> gq1OutLocal_;
    AscendC::LocalTensor<int8_t> gq2OutLocal_;
    AscendC::LocalTensor<float> y3OutLocal_;
    AscendC::LocalTensor<dataType> y4OutLocal_;
    AscendC::LocalTensor<dataType> xAddOutLocal_;
    AscendC::LocalTensor<float> scale1OutLocal_;
    AscendC::LocalTensor<float> scale2OutLocal_;
    AscendC::LocalTensor<float> gammaFp32Local_;
    AscendC::LocalTensor<float> gammaTileLocal_;
    AscendC::LocalTensor<uint8_t> gammaBcastTmpLocal_;
    AscendC::LocalTensor<float> betaFp32Local_;
    AscendC::LocalTensor<float> betaTileLocal_;
    AscendC::LocalTensor<uint8_t> betaBcastTmpLocal_;
};

// =========================================================================
// Strategy 2: single_row — N > 1024, one row at a time
// =========================================================================

template <typename dataType>
class AddRmsNormDynamicQuantV2SingleRowKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta,
        GM_ADDR smooth1, GM_ADDR smooth2,
        GM_ADDR gq1, GM_ADDR gq2, GM_ADDR y3_fp32, GM_ADDR y4_dtype,
        GM_ADDR x_add_out, GM_ADDR scale1, GM_ADDR scale2,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float eps, float invN,
        float inv127)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->eps = eps;
        this->invN = invN;
        this->inv127 = inv127;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(beta), N);
        smooth1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth1), N);
        smooth2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth2), N);
        gq1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(gq1), static_cast<uint64_t>(M) * N);
        gq2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(gq2), static_cast<uint64_t>(M) * N);
        y3Fp32GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y3_fp32), static_cast<uint64_t>(M) * N);
        y4DtypeGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y4_dtype), static_cast<uint64_t>(M) * N);
        xAddGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_add_out), static_cast<uint64_t>(M) * N);
        scale1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale1), M);
        scale2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale2), M);

        if ASCEND_IS_AIV {
            subBlockRows_ = blockM / AscendC::GetSubBlockNum();

            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
            pipe.InitBuffer(betaBuf_, N * sizeof(dataType));
            pipe.InitBuffer(smooth1Buf_, N * sizeof(dataType));
            pipe.InitBuffer(smooth2Buf_, N * sizeof(dataType));
            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(gq1OutQueue_, BUFFER_NUM, N * sizeof(int8_t));
            pipe.InitBuffer(gq2OutQueue_, BUFFER_NUM, N * sizeof(int8_t));
            pipe.InitBuffer(y3OutQueue_, BUFFER_NUM, N * sizeof(float));
            pipe.InitBuffer(y4OutQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(scale1OutQueue_, BUFFER_NUM, sizeof(float));
            pipe.InitBuffer(scale2OutQueue_, BUFFER_NUM, sizeof(float));

            pipe.InitBuffer(tempBufA_, N * sizeof(float));
            pipe.InitBuffer(tempBufB_, N * sizeof(float));
            pipe.InitBuffer(tempBufC_, N * sizeof(float));
            pipe.InitBuffer(yNormFp32Buf_, N * sizeof(float));
            pipe.InitBuffer(quantHalfBuf_, N * sizeof(half));
            pipe.InitBuffer(reduceTmpBuf_, 2 * N * sizeof(float));
            pipe.InitBuffer(bcastTmpBuf_, 2 * N * sizeof(uint8_t));
            pipe.InitBuffer(sumBuf_, sizeof(float));
            pipe.InitBuffer(rstdBuf_, sizeof(float));

            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(x1CastBuf_, N * sizeof(float));
                pipe.InitBuffer(x2CastBuf_, N * sizeof(float));
                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
                pipe.InitBuffer(betaCastBuf_, N * sizeof(float));
                pipe.InitBuffer(smooth1CastBuf_, N * sizeof(float));
                pipe.InitBuffer(smooth2CastBuf_, N * sizeof(float));
                pipe.InitBuffer(xAddCastBuf_, N * sizeof(float));
                pipe.InitBuffer(y4CastBuf_, N * sizeof(float));
            }

            // Pre-load gamma, beta, smooth1, smooth2
            gammaInLocal_ = gammaBuf_.Get<dataType>();
            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
            CastInputToFloat<dataType>(gammaFp32Local_, gammaInLocal_, gammaCastBuf_, N);

            betaInLocal_ = betaBuf_.Get<dataType>();
            LoadGmToUb(betaInLocal_, betaGM_, static_cast<uint32_t>(N));
            CastInputToFloat<dataType>(betaFp32Local_, betaInLocal_, betaCastBuf_, N);

            smooth1InLocal_ = smooth1Buf_.Get<dataType>();
            LoadGmToUb(smooth1InLocal_, smooth1GM_, static_cast<uint32_t>(N));
            CastInputToFloat<dataType>(smooth1Fp32Local_, smooth1InLocal_, smooth1CastBuf_, N);

            smooth2InLocal_ = smooth2Buf_.Get<dataType>();
            LoadGmToUb(smooth2InLocal_, smooth2GM_, static_cast<uint32_t>(N));
            CastInputToFloat<dataType>(smooth2Fp32Local_, smooth2InLocal_, smooth2CastBuf_, N);
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();
            const int mNum = (M + blockM - 1) / blockM;

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= mNum) { continue; }
                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) { ProcessRow(rowIdx); }
                }
            }
        }
    }

private:
    __aicore__ inline void CopyInX1(int32_t rowIdx)
    {
        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        x1InQueue_.EnQue(x1InLocal_);
    }

    __aicore__ inline void CopyInX2(int32_t rowIdx)
    {
        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        x2InQueue_.EnQue(x2InLocal_);
    }

    __aicore__ inline void CopyOutGq1(int32_t rowIdx)
    {
        gq1OutLocal_ = gq1OutQueue_.DeQue<int8_t>();
        StoreUbToGm(gq1GM_[static_cast<uint64_t>(rowIdx) * N], gq1OutLocal_, static_cast<uint32_t>(N));
        gq1OutQueue_.FreeTensor(gq1OutLocal_);
    }

    __aicore__ inline void CopyOutGq2(int32_t rowIdx)
    {
        gq2OutLocal_ = gq2OutQueue_.DeQue<int8_t>();
        StoreUbToGm(gq2GM_[static_cast<uint64_t>(rowIdx) * N], gq2OutLocal_, static_cast<uint32_t>(N));
        gq2OutQueue_.FreeTensor(gq2OutLocal_);
    }

    __aicore__ inline void CopyOutY3(int32_t rowIdx)
    {
        y3OutLocal_ = y3OutQueue_.DeQue<float>();
        StoreUbToGm(y3Fp32GM_[static_cast<uint64_t>(rowIdx) * N], y3OutLocal_, static_cast<uint32_t>(N));
        y3OutQueue_.FreeTensor(y3OutLocal_);
    }

    __aicore__ inline void CopyOutY4(int32_t rowIdx)
    {
        y4OutLocal_ = y4OutQueue_.DeQue<dataType>();
        StoreUbToGm(y4DtypeGM_[static_cast<uint64_t>(rowIdx) * N], y4OutLocal_, static_cast<uint32_t>(N));
        y4OutQueue_.FreeTensor(y4OutLocal_);
    }

    __aicore__ inline void CopyOutXAdd(int32_t rowIdx)
    {
        xAddOutLocal_ = xAddOutQueue_.DeQue<dataType>();
        StoreUbToGm(xAddGM_[static_cast<uint64_t>(rowIdx) * N], xAddOutLocal_, static_cast<uint32_t>(N));
        xAddOutQueue_.FreeTensor(xAddOutLocal_);
    }

    __aicore__ inline void CopyOutScale1(int32_t rowIdx)
    {
        scale1OutLocal_ = scale1OutQueue_.DeQue<float>();
        StoreUbToGm(scale1GM_[rowIdx], scale1OutLocal_, 1);
        scale1OutQueue_.FreeTensor(scale1OutLocal_);
    }

    __aicore__ inline void CopyOutScale2(int32_t rowIdx)
    {
        scale2OutLocal_ = scale2OutQueue_.DeQue<float>();
        StoreUbToGm(scale2GM_[rowIdx], scale2OutLocal_, 1);
        scale2OutQueue_.FreeTensor(scale2OutLocal_);
    }

    __aicore__ inline void ComputeRow()
    {
        gq1OutLocal_ = gq1OutQueue_.AllocTensor<int8_t>();
        gq2OutLocal_ = gq2OutQueue_.AllocTensor<int8_t>();
        y3OutLocal_ = y3OutQueue_.AllocTensor<float>();
        y4OutLocal_ = y4OutQueue_.AllocTensor<dataType>();
        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();

        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
        AscendC::LocalTensor<float> yNormFp32 = yNormFp32Buf_.Get<float>();
        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
        AscendC::LocalTensor<float> reduceTmp = reduceTmpBuf_.Get<float>();

        // DeQue x1, x2
        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, N);
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, N);

        // ---- Add + RMSNorm ----
        // x_add = x1 + x2 → tempC
        AscendC::Add(tempC, tempA, tempB, N);

        // Save x_add → xAddOutLocal_
        CastOutputBack<dataType>(xAddOutLocal_, tempC, N);

        // x_add^2 → tempA
        AscendC::Mul(tempA, tempC, tempC, N);
        AscendC::ReduceSum<float>(sumBuf, tempA, reduceTmp, N);

        float meanSq = sumBuf.GetValue(0) * invN + eps;
        AscendC::Duplicate(sumBuf, meanSq, 1);
        AscendC::Rsqrt(rstdBuf, sumBuf, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        float invRmsVal = rstdBuf.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // y = x_add * rstd * gamma + beta (RMSNorm with bias)
        AscendC::Muls(tempC, tempC, invRmsVal, N);
        AscendC::Mul(tempC, tempC, gammaFp32Local_, N);
        AscendC::Add(tempC, tempC, betaFp32Local_, N);

        // Save y to yNormFp32
        AscendC::DataCopy(yNormFp32, tempC, N);

        // Write y3_out (FP32)
        AscendC::DataCopy(y3OutLocal_, yNormFp32, N);

        // Write y4_out (orig dtype)
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(y4OutLocal_, yNormFp32, N);
        } else {
            CastOutputBack<dataType>(y4OutLocal_, yNormFp32, N);
        }

        // ---- DynamicQuant 1 ----
        // smooth_x1 = y * smooth1
        AscendC::Mul(tempA, yNormFp32, smooth1Fp32Local_, N);
        // max_abs1 = max(|smooth_x1|)
        AscendC::Abs(tempB, tempA, N);
        AscendC::ReduceMax<float>(sumBuf, tempB, reduceTmp, N);
        AscendC::PipeBarrier<PIPE_ALL>();
        float maxAbs1 = sumBuf.GetValue(0);
        maxAbs1 = (maxAbs1 > 1e-8f) ? maxAbs1 : 1e-8f;

        float scale1Val = maxAbs1 * inv127;
        AscendC::Duplicate(scale1OutLocal_, scale1Val, 1);

        AscendC::Muls(tempA, tempA, 1.0f / scale1Val, N);
        AscendC::Maxs(tempA, tempA, -128.0f, N);
        AscendC::Mins(tempA, tempA, 127.0f, N);
        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(gq1OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);

        // ---- DynamicQuant 2 ----
        AscendC::Mul(tempA, yNormFp32, smooth2Fp32Local_, N);
        AscendC::Abs(tempB, tempA, N);
        AscendC::ReduceMax<float>(sumBuf, tempB, reduceTmp, N);
        AscendC::PipeBarrier<PIPE_ALL>();
        float maxAbs2 = sumBuf.GetValue(0);
        maxAbs2 = (maxAbs2 > 1e-8f) ? maxAbs2 : 1e-8f;

        float scale2Val = maxAbs2 * inv127;
        AscendC::Duplicate(scale2OutLocal_, scale2Val, 1);

        AscendC::Muls(tempA, tempA, 1.0f / scale2Val, N);
        AscendC::Maxs(tempA, tempA, -128.0f, N);
        AscendC::Mins(tempA, tempA, 127.0f, N);
        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(gq2OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        gq1OutQueue_.EnQue(gq1OutLocal_);
        gq2OutQueue_.EnQue(gq2OutLocal_);
        y3OutQueue_.EnQue(y3OutLocal_);
        y4OutQueue_.EnQue(y4OutLocal_);
        xAddOutQueue_.EnQue(xAddOutLocal_);
        scale1OutQueue_.EnQue(scale1OutLocal_);
        scale2OutQueue_.EnQue(scale2OutLocal_);
    }

    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        CopyInX1(rowIdx);
        CopyInX2(rowIdx);
        ComputeRow();
        CopyOutGq1(rowIdx);
        CopyOutGq2(rowIdx);
        CopyOutY3(rowIdx);
        CopyOutY4(rowIdx);
        CopyOutXAdd(rowIdx);
        CopyOutScale1(rowIdx);
        CopyOutScale2(rowIdx);
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    float eps = 0.0f;
    float invN = 0.0f;
    float inv127 = 0.0f;
    int32_t subBlockRows_ = 0;

    AscendC::TPipe pipe;

    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<dataType> gammaGM_;
    AscendC::GlobalTensor<dataType> betaGM_;
    AscendC::GlobalTensor<dataType> smooth1GM_;
    AscendC::GlobalTensor<dataType> smooth2GM_;
    AscendC::GlobalTensor<int8_t> gq1GM_;
    AscendC::GlobalTensor<int8_t> gq2GM_;
    AscendC::GlobalTensor<float> y3Fp32GM_;
    AscendC::GlobalTensor<dataType> y4DtypeGM_;
    AscendC::GlobalTensor<dataType> xAddGM_;
    AscendC::GlobalTensor<float> scale1GM_;
    AscendC::GlobalTensor<float> scale2GM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> gq1OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> gq2OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> y3OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> y4OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> xAddOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> scale1OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> scale2OutQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaBuf_;
