template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchAddRmsNormDynamicQuantV2(
    GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta,
    GM_ADDR smooth1, GM_ADDR smooth2,
    GM_ADDR gq1, GM_ADDR gq2, GM_ADDR y3_fp32, GM_ADDR y4_dtype,
    GM_ADDR x_add_out, GM_ADDR scale1, GM_ADDR scale2,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float eps, float invN,
    float inv127, int64_t dtypeFlag, ExtraArgs... extraArgs)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x1, x2, gamma, beta, smooth1, smooth2,
                    gq1, gq2, y3_fp32, y4_dtype,
                    x_add_out, scale1, scale2,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    extraArgs..., eps, invN, inv127);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x1, x2, gamma, beta, smooth1, smooth2,
                    gq1, gq2, y3_fp32, y4_dtype,
                    x_add_out, scale1, scale2,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    extraArgs..., eps, invN, inv127);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x1, x2, gamma, beta, smooth1, smooth2,
                    gq1, gq2, y3_fp32, y4_dtype,
                    x_add_out, scale1, scale2,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    extraArgs..., eps, invN, inv127);
        kernel.Process();
    }
}

