// AddRmsNormDynamicQuantV2 op_host — tiling + strategy dispatch + EXEC_KERNEL_CMD
// V2 adds beta (RMSNorm bias) and y3 (FP32), y4 (orig dtype) outputs

#include <algorithm>
#include <cstdint>
#include <vector>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_add_rms_norm_dynamic_quant_v2_merge_n.h"
#include "aclrtlaunch_add_rms_norm_dynamic_quant_v2_single_row.h"

constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_ROW_FACTOR = 8;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

namespace ascend_kernel {

std::vector<at::Tensor> add_rms_norm_dynamic_quant_v2(
    const at::Tensor &x1, const at::Tensor &x2,
    const at::Tensor &gamma, const at::Tensor &beta, double eps,
    const at::Tensor &smooth1, const at::Tensor &smooth2)
{
    TORCH_CHECK(x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
                   x1.scalar_type() == at::kBFloat16,
        "x1 must be float16, float32, or bfloat16");
    TORCH_CHECK(x1.scalar_type() == x2.scalar_type(),
        "x1 and x2 must have the same dtype");
    TORCH_CHECK(gamma.scalar_type() == x1.scalar_type(),
        "gamma must have the same dtype as x1/x2");
    TORCH_CHECK(beta.scalar_type() == x1.scalar_type(),
        "beta must have the same dtype as x1/x2");
    TORCH_CHECK(smooth1.scalar_type() == x1.scalar_type(),
        "smooth1 must have the same dtype as x1/x2");
    TORCH_CHECK(smooth2.scalar_type() == x1.scalar_type(),
        "smooth2 must have the same dtype as x1/x2");
    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [N]");
    TORCH_CHECK(beta.dim() == 1, "beta must be 1D [N]");
    TORCH_CHECK(x1.sizes().back() == gamma.sizes()[0],
        "gamma shape mismatch");
    TORCH_CHECK(x1.sizes() == x2.sizes(), "x1 and x2 must have the same shape");

    auto origShape = x1.sizes();
    int32_t N = static_cast<int32_t>(x1.sizes().back());
    int64_t M = x1.numel() / N;

    at::Tensor x1_2d = x1.contiguous().view({M, N});
    at::Tensor x2_2d = x2.contiguous().view({M, N});

    int32_t M_i32 = static_cast<int32_t>(M);
    int32_t mNum = (M_i32 + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // Output tensors
    at::Tensor gq1 = at::empty({M, N}, x1_2d.options().dtype(at::kChar));       // int8
    at::Tensor gq2 = at::empty({M, N}, x1_2d.options().dtype(at::kChar));       // int8
    at::Tensor y3 = at::empty({M, N}, at::TensorOptions().dtype(at::kFloat).device(x1.device()));  // float32
    at::Tensor y4 = at::empty_like(x1_2d);                                                          // orig dtype
    at::Tensor x_add = at::empty_like(x1_2d);                                                        // orig dtype
    at::Tensor scale1 = at::empty({static_cast<int64_t>(M)}, at::TensorOptions().dtype(at::kFloat).device(x1.device()));
    at::Tensor scale2 = at::empty({static_cast<int64_t>(M)}, at::TensorOptions().dtype(at::kFloat).device(x1.device()));

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x1_2d.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x1_2d.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // Left-value params for EXEC_KERNEL_CMD
    int32_t blockM = DEFAULT_BLOCK_M;
    int32_t rowFactor = DEFAULT_ROW_FACTOR;
    float epsVal = static_cast<float>(eps);
    float invN = 1.0f / static_cast<float>(N);
    float inv127 = 1.0f / 127.0f;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Strategy dispatch based on N
    if (N <= 1024) {
        EXEC_KERNEL_CMD(add_rms_norm_dynamic_quant_v2_merge_n, blockDim,
                        x1_2d, x2_2d, gamma, beta, smooth1, smooth2,
                        gq1, gq2, y3, y4, x_add, scale1, scale2,
                        M_i32, N, blockM, usedCoreNum,
                        tasksPerCore, rowFactor, epsVal, invN, inv127, dtypeFlag);
    } else {
        EXEC_KERNEL_CMD(add_rms_norm_dynamic_quant_v2_single_row, blockDim,
                        x1_2d, x2_2d, gamma, beta, smooth1, smooth2,
                        gq1, gq2, y3, y4, x_add, scale1, scale2,
                        M_i32, N, blockM, usedCoreNum,
                        tasksPerCore, epsVal, invN, inv127, dtypeFlag);
    }

    return {gq1, gq2, y3, y4, x_add, scale1, scale2};
}

}  // namespace ascend_kernel
