// AscendC AddRmsNormDynamicQuantV2 kernel
// V2 adds beta (RMSNorm bias), y3 (FP32 output), y4 (dtype output)
// Fuses: x_add = x1 + x2 → RMSNorm(with beta) → per-row DynamicQuant(smooth1) → per-row DynamicQuant(smooth2)
// Outputs: gq1(int8), gq2(int8), y3(float32), y4(dtype), x_out(dtype), scale1(float32), scale2(float32)
// Strategies: merge_n (N <= 1024), single_row (N > 1024)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers — identical to V1
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void CastInputToFloat(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void CastOutputBack(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Strategy 1: merge_n — N <= 1024, merge kMergeRowFactor rows into one tile
// =========================================================================

template <typename dataType>
class AddRmsNormDynamicQuantV2MergeNKernel {
public:
    static constexpr int kMergeRowFactor = 8;

    __aicore__ inline void Init(
        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta,
        GM_ADDR smooth1, GM_ADDR smooth2,
        GM_ADDR gq1, GM_ADDR gq2, GM_ADDR y3_fp32, GM_ADDR y4_dtype,
        GM_ADDR x_add_out, GM_ADDR scale1, GM_ADDR scale2,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
        float inv127)
    {
        this->M = M; this->N = N; this->blockM = blockM;
        this->usedCoreNum = usedCoreNum; this->tasksPerCore = tasksPerCore;
        this->rowFactor = rowFactor; this->eps = eps;
        this->invN = invN; this->inv127 = inv127;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(beta), N);
        smooth1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth1), N);
        smooth2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth2), N);
        gq1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(gq1), static_cast<uint64_t>(M) * N);
        gq2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(gq2), static_cast<uint64_t>(M) * N);
        y3Fp32GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y3_fp32), static_cast<uint64_t>(M) * N);
        y4DtypeGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y4_dtype), static_cast<uint64_t>(M) * N);
        xAddGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_add_out), static_cast<uint64_t>(M) * N);
        scale1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale1), M);
        scale2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale2), M);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
        rowLoops_ = subBlockRows_ / rowFactor;
        const int32_t tileElems = kMergeRowFactor * N;

        pipe.InitBuffer(x1InQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
        pipe.InitBuffer(x2InQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
        pipe.InitBuffer(gq1OutQueue_, BUFFER_NUM, tileElems * sizeof(int8_t));
        pipe.InitBuffer(gq2OutQueue_, BUFFER_NUM, tileElems * sizeof(int8_t));
        pipe.InitBuffer(y3OutQueue_, BUFFER_NUM, tileElems * sizeof(float));
        pipe.InitBuffer(y4OutQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
        pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
        pipe.InitBuffer(scale1OutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(float));
        pipe.InitBuffer(scale2OutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(float));

        // Pre-load static buffers: gamma only (beta/smooth loaded on-the-fly)
        pipe.InitBuffer(gamma1DBuf_, N * sizeof(dataType));
        pipe.InitBuffer(gammaTileBuf_, tileElems * sizeof(float));
        pipe.InitBuffer(gammaBcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
        pipe.InitBuffer(smooth1_1DBuf_, N * sizeof(dataType));
        pipe.InitBuffer(smooth1TileBuf_, tileElems * sizeof(float));
        pipe.InitBuffer(smooth1BcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
        pipe.InitBuffer(smooth2_1DBuf_, N * sizeof(dataType));
        pipe.InitBuffer(smooth2TileBuf_, tileElems * sizeof(float));
        pipe.InitBuffer(smooth2BcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));

        // Compute buffers
        pipe.InitBuffer(tempBufA_, tileElems * sizeof(float));
        pipe.InitBuffer(tempBufB_, tileElems * sizeof(float));
        pipe.InitBuffer(tempBufC_, tileElems * sizeof(float));
        pipe.InitBuffer(xAddFp32Buf_, tileElems * sizeof(float));
        pipe.InitBuffer(yNormFp32Buf_, tileElems * sizeof(float));
        pipe.InitBuffer(quantHalfBuf_, tileElems * sizeof(half));
        pipe.InitBuffer(reduceTmpBuf_, 2 * tileElems * sizeof(uint8_t));
        pipe.InitBuffer(bcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
        pipe.InitBuffer(sumBuf_, kMergeRowFactor * sizeof(float));
        pipe.InitBuffer(rstdBuf_, kMergeRowFactor * sizeof(float));
        pipe.InitBuffer(scaleBuf_, kMergeRowFactor * sizeof(float));
        pipe.InitBuffer(maxAbsBuf_, kMergeRowFactor * sizeof(float));

        // Cast buffers for fp16/bf16
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(x1CastBuf_, tileElems * sizeof(float));
            pipe.InitBuffer(x2CastBuf_, tileElems * sizeof(float));
            pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
            pipe.InitBuffer(smooth1CastBuf_, N * sizeof(float));
            pipe.InitBuffer(smooth2CastBuf_, N * sizeof(float));
            pipe.InitBuffer(xAddCastBuf_, tileElems * sizeof(float));
            pipe.InitBuffer(y4CastBuf_, tileElems * sizeof(float));
        }

        // Pre-load & broadcast gamma
        const uint32_t gammaSrcShape[2] = {1U, static_cast<uint32_t>(N)};
        const uint32_t gammaDstShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
        gammaInLocal_ = gamma1DBuf_.Get<dataType>();
        LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        CastInputToFloat<dataType>(gammaFp32Local_, gammaInLocal_, gammaCastBuf_, N);
        gammaTileLocal_ = gammaTileBuf_.Get<float>();
        gammaBcastTmpLocal_ = gammaBcastTmpBuf_.Get<uint8_t>();
        AscendC::PipeBarrier<PIPE_ALL>();
        AscendC::Broadcast<float, 2, 0>(gammaTileLocal_, gammaFp32Local_,
            gammaDstShape, gammaSrcShape, gammaBcastTmpLocal_);
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= (M + blockM - 1) / blockM) { continue; }

                for (int r = 0; r < rowLoops_; ++r) {
                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
                    const int validRows = M - rowBase;
                    if (validRows > 0) {
                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
                    }
                }
            }
        }
    }

