    // Pre-load ANY 1D[N] tensor from GM and broadcast to (kMergeRowFactor, N) float
    __aicore__ inline void Preload1D(
        AscendC::GlobalTensor<dataType> &gmSrc,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf1D,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &bufTile,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &bufBcastTmp,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
        AscendC::LocalTensor<dataType> &inLocal,
        AscendC::LocalTensor<float> &fp32Local,
        AscendC::LocalTensor<float> &tileLocal,
        AscendC::LocalTensor<uint8_t> &bcastTmpLocal)
    {
        inLocal = buf1D.Get<dataType>();
        LoadGmToUb(inLocal, gmSrc, static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        CastInputToFloat<dataType>(fp32Local, inLocal, castBuf, N);
        tileLocal = bufTile.Get<float>();
        bcastTmpLocal = bufBcastTmp.Get<uint8_t>();
        AscendC::PipeBarrier<PIPE_ALL>();
        const uint32_t srcShape[2] = {1U, static_cast<uint32_t>(N)};
        const uint32_t dstShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
        AscendC::Broadcast<float, 2, 0>(tileLocal, fp32Local, dstShape, srcShape, bcastTmpLocal);
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void ComputeDynamicQuant(
        AscendC::LocalTensor<float> &yFp32,
        AscendC::LocalTensor<float> &smoothTileFp32,
        AscendC::LocalTensor<float> &tempA,
        AscendC::LocalTensor<float> &tempB,
        AscendC::LocalTensor<float> &tempC,
        AscendC::LocalTensor<float> &outScale,
        AscendC::LocalTensor<int8_t> &outInt8,
        AscendC::LocalTensor<uint8_t> &reduceTmp,
        AscendC::LocalTensor<uint8_t> &bcastTmp,
        AscendC::LocalTensor<float> &maxAbsBuf,
        AscendC::LocalTensor<half> &quantHalf,
        int32_t tileSize)
    {
        const uint32_t reduceShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
        const uint32_t scaleSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
        const uint32_t scaleDstShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};

        // smooth_x = y * smooth
        AscendC::Mul(tempA, yFp32, smoothTileFp32, tileSize);

        // max_abs = reduce_max(|smooth_x|)
        AscendC::Abs(tempB, tempA, tileSize);
        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::AR, false>(
            maxAbsBuf, tempB, reduceTmp, reduceShape, true);

        // scale = max(max_abs, 1e-8) * inv127
        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, kMergeRowFactor);
        AscendC::Muls(outScale, maxAbsBuf, inv127, kMergeRowFactor);

        // q = clamp(round(smooth_x / scale), -128, 127)
        AscendC::Broadcast<float, 2, 1>(tempC, outScale, scaleDstShape, scaleSrcShape, bcastTmp);
        AscendC::Div(tempA, tempA, tempC, tileSize);
        AscendC::Maxs(tempA, tempA, -128.0f, tileSize);
        AscendC::Mins(tempA, tempA, 127.0f, tileSize);
        // Cast: float -> half -> int8
        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, tileSize);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(outInt8, quantHalf, AscendC::RoundMode::CAST_RINT, tileSize);
    }

    __aicore__ inline void ComputeRows(int32_t tileSize)
    {
        gq1OutLocal_ = gq1OutQueue_.AllocTensor<int8_t>();
        gq2OutLocal_ = gq2OutQueue_.AllocTensor<int8_t>();
        y3OutLocal_ = y3OutQueue_.AllocTensor<float>();
        y4OutLocal_ = y4OutQueue_.AllocTensor<dataType>();
        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();

        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
        AscendC::LocalTensor<float> xAddFp32 = xAddFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> yNormFp32 = yNormFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
        AscendC::LocalTensor<float> scaleBuf = scaleBuf_.Get<float>();
        AscendC::LocalTensor<float> maxAbsBuf = maxAbsBuf_.Get<float>();
        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();
        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
        AscendC::LocalTensor<uint8_t> bcastTmp = bcastTmpBuf_.Get<uint8_t>();

        const uint32_t reduceShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
        const uint32_t scaleSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
        const uint32_t scaleDstShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};

        // DeQue x1, x2
        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, tileSize);

        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, tileSize);

        // ---- Add + RMSNorm (with beta) ----
        // x_add = x1 + x2
        AscendC::Add(tempC, tempA, tempB, tileSize);
        AscendC::DataCopy(xAddFp32, tempC, tileSize);
        CastOutputBack<dataType>(xAddOutLocal_, xAddFp32, tileSize);

        // x_add^2
        AscendC::Mul(tempA, tempC, tempC, tileSize);

        // sum_sq = reduce_sum(x_add^2)
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumBuf, tempA, reduceTmp, reduceShape, true);

        // rstd = rsqrt(sum_sq * invN + eps)
        AscendC::Muls(rstdBuf, sumBuf, invN, kMergeRowFactor);
        AscendC::Adds(rstdBuf, rstdBuf, eps, kMergeRowFactor);
        AscendC::Rsqrt(rstdBuf, rstdBuf, kMergeRowFactor);
        AscendC::PipeBarrier<PIPE_V>();

        // y = x_add * rstd * gamma
        AscendC::Broadcast<float, 2, 1>(scaleBuf, rstdBuf, scaleDstShape, scaleSrcShape, bcastTmp);
        AscendC::Mul(tempC, xAddFp32, scaleBuf, tileSize);
        AscendC::Mul(tempC, tempC, gammaTileLocal_, tileSize);

        // V2: Add beta (RMSNorm bias) - load beta on-the-fly
        // Reuse smooth1 buffer pair for beta (loaded on-the-fly, used once then discarded)
        {
            AscendC::LocalTensor<dataType> betaIn;
            AscendC::LocalTensor<float> betaFp32;
            AscendC::LocalTensor<float> betaTile;
            AscendC::LocalTensor<uint8_t> betaBcastTmp;
            Preload1D(betaGM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
                smooth1CastBuf_, betaIn, betaFp32, betaTile, betaBcastTmp);
            AscendC::Add(tempC, tempC, betaTile, tileSize);
        }

        // Save y (FP32)
        AscendC::DataCopy(yNormFp32, tempC, tileSize);
        AscendC::DataCopy(y3OutLocal_, yNormFp32, tileSize);

        // Write y4_out (orig dtype)
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(y4OutLocal_, yNormFp32, tileSize);
        } else {
            CastOutputBack<dataType>(y4OutLocal_, yNormFp32, tileSize);
        }

        // ---- DynamicQuant 1 ----
        AscendC::LocalTensor<dataType> smooth1InLocal;
        AscendC::LocalTensor<float> smooth1Fp32Local;
        AscendC::LocalTensor<float> smooth1TileLocal;
        AscendC::LocalTensor<uint8_t> smooth1BcastTmp;
        Preload1D(smooth1GM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
            smooth1CastBuf_, smooth1InLocal, smooth1Fp32Local, smooth1TileLocal, smooth1BcastTmp);

        ComputeDynamicQuant(yNormFp32, smooth1TileLocal, tempA, tempB, xAddFp32,
            scale1OutLocal_, gq1OutLocal_, reduceTmp, bcastTmp, maxAbsBuf, quantHalf, tileSize);

        // ---- DynamicQuant 2 ----
        AscendC::LocalTensor<dataType> smooth2InLocal;
        AscendC::LocalTensor<float> smooth2Fp32Local;
        AscendC::LocalTensor<float> smooth2TileLocal;
        AscendC::LocalTensor<uint8_t> smooth2BcastTmp;
        Preload1D(smooth2GM_, smooth2_1DBuf_, smooth2TileBuf_, smooth2BcastTmpBuf_,
            smooth2CastBuf_, smooth2InLocal, smooth2Fp32Local, smooth2TileLocal, smooth2BcastTmp);

        ComputeDynamicQuant(yNormFp32, smooth2TileLocal, tempA, tempB, xAddFp32,
            scale2OutLocal_, gq2OutLocal_, reduceTmp, bcastTmp, maxAbsBuf, quantHalf, tileSize);

        // EnQue outputs
        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        gq1OutQueue_.EnQue(gq1OutLocal_);
        gq2OutQueue_.EnQue(gq2OutLocal_);
        y3OutQueue_.EnQue(y3OutLocal_);
        y4OutQueue_.EnQue(y4OutLocal_);
        xAddOutQueue_.EnQue(xAddOutLocal_);
        scale1OutQueue_.EnQue(scale1OutLocal_);
        scale2OutQueue_.EnQue(scale2OutLocal_);
    }

    // Single-row fallback (validRows < kMergeRowFactor)
    __aicore__ inline void ComputeSingleRow()
    {
        gq1OutLocal_ = gq1OutQueue_.AllocTensor<int8_t>();
        gq2OutLocal_ = gq2OutQueue_.AllocTensor<int8_t>();
        y3OutLocal_ = y3OutQueue_.AllocTensor<float>();
        y4OutLocal_ = y4OutQueue_.AllocTensor<dataType>();
        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();

        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
        AscendC::LocalTensor<float> xAddFp32 = xAddFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> yNormFp32 = yNormFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
        AscendC::LocalTensor<float> maxAbsBuf = maxAbsBuf_.Get<float>();
        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();
        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
        AscendC::LocalTensor<uint8_t> bcastTmp = bcastTmpBuf_.Get<uint8_t>();

        const uint32_t rowReduceShape[2] = {1U, static_cast<uint32_t>(N)};
        const uint32_t qScaleSrcShape[2] = {1U, 1U};
        const uint32_t qScaleDstShape[2] = {1U, static_cast<uint32_t>(N)};

        // DeQue x1, x2
        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, N);
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, N);

        // x_add = x1 + x2
        AscendC::Add(tempC, tempA, tempB, N);
        AscendC::DataCopy(xAddFp32, tempC, N);
        CastOutputBack<dataType>(xAddOutLocal_, xAddFp32, N);

        // sum_sq
        AscendC::Mul(tempA, tempC, tempC, N);
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::RA, false>(
            sumBuf, tempA, reduceTmp, rowReduceShape, true);
        float meanSq = sumBuf.GetValue(0) * invN + eps;
        AscendC::Duplicate(sumBuf, meanSq, 1);
        AscendC::Rsqrt(rstdBuf, sumBuf, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        float invRmsVal = rstdBuf.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // y = x_add * rstd * gamma
        AscendC::Muls(tempC, xAddFp32, invRmsVal, N);
        AscendC::Mul(tempC, tempC, gammaTileLocal_, N);

        // V2: Add beta
        {
            AscendC::LocalTensor<dataType> betaIn;
            AscendC::LocalTensor<float> betaFp32;
            AscendC::LocalTensor<float> betaTile;
            AscendC::LocalTensor<uint8_t> betaBcastTmp;
            Preload1D(betaGM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
                smooth1CastBuf_, betaIn, betaFp32, betaTile, betaBcastTmp);
            AscendC::Add(tempC, tempC, betaTile, N);
        }

        // Save y
        AscendC::DataCopy(yNormFp32, tempC, N);
        AscendC::DataCopy(y3OutLocal_, yNormFp32, N);

        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(y4OutLocal_, yNormFp32, N);
        } else {
            CastOutputBack<dataType>(y4OutLocal_, yNormFp32, N);
        }

        // DynamicQuant 1
        AscendC::LocalTensor<dataType> smooth1InLocal;
        AscendC::LocalTensor<float> smooth1Fp32Local;
        AscendC::LocalTensor<float> smooth1TileLocal;
        AscendC::LocalTensor<uint8_t> smooth1BcastTmp;
        Preload1D(smooth1GM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
            smooth1CastBuf_, smooth1InLocal, smooth1Fp32Local, smooth1TileLocal, smooth1BcastTmp);

        AscendC::Mul(tempA, yNormFp32, smooth1TileLocal, N);
        AscendC::Abs(tempB, tempA, N);
        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::RA, false>(
            maxAbsBuf, tempB, reduceTmp, rowReduceShape, true);
        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, 1);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(scale1OutLocal_, maxAbsBuf, inv127, 1);

        AscendC::Broadcast<float, 2, 1>(tempB, scale1OutLocal_, qScaleDstShape, qScaleSrcShape, bcastTmp);
        AscendC::Div(tempA, tempA, tempB, N);
        AscendC::Maxs(tempA, tempA, -128.0f, N);
        AscendC::Mins(tempA, tempA, 127.0f, N);
        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(gq1OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);

        // DynamicQuant 2
        AscendC::LocalTensor<dataType> smooth2InLocal;
        AscendC::LocalTensor<float> smooth2Fp32Local;
        AscendC::LocalTensor<float> smooth2TileLocal;
        AscendC::LocalTensor<uint8_t> smooth2BcastTmp;
        Preload1D(smooth2GM_, smooth2_1DBuf_, smooth2TileBuf_, smooth2BcastTmpBuf_,
            smooth2CastBuf_, smooth2InLocal, smooth2Fp32Local, smooth2TileLocal, smooth2BcastTmp);

        AscendC::Mul(tempA, yNormFp32, smooth2TileLocal, N);
        AscendC::Abs(tempB, tempA, N);
        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::RA, false>(
            maxAbsBuf, tempB, reduceTmp, rowReduceShape, true);
        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, 1);
        AscendC::Muls(scale2OutLocal_, maxAbsBuf, inv127, 1);

        AscendC::Broadcast<float, 2, 1>(tempB, scale2OutLocal_, qScaleDstShape, qScaleSrcShape, bcastTmp);
        AscendC::Div(tempA, tempA, tempB, N);
        AscendC::Maxs(tempA, tempA, -128.0f, N);
        AscendC::Mins(tempA, tempA, 127.0f, N);
        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(gq2OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        gq1OutQueue_.EnQue(gq1OutLocal_);
        gq2OutQueue_.EnQue(gq2OutLocal_);
        y3OutQueue_.EnQue(y3OutLocal_);
        y4OutQueue_.EnQue(y4OutLocal_);
        xAddOutQueue_.EnQue(xAddOutLocal_);
        scale1OutQueue_.EnQue(scale1OutLocal_);
        scale2OutQueue_.EnQue(scale2OutLocal_);
    }

    __aicore__ inline void ProcessSingleRow(int32_t rowIdx)
    {
        CopyInX1(rowIdx, N);
        CopyInX2(rowIdx, N);
        ComputeSingleRow();
        CopyOutGq1(rowIdx, N);
        CopyOutGq2(rowIdx, N);
        CopyOutY3Fp32(rowIdx, N);
        CopyOutY4Dtype(rowIdx, N);
        CopyOutXAdd(rowIdx, N);
        CopyOutScale1(rowIdx, 1);
        CopyOutScale2(rowIdx, 1);
    }

    __aicore__ inline void ProcessRows(int32_t rowBase, int32_t validRows)
    {
        if (validRows < kMergeRowFactor) {
            for (int r = 0; r < validRows; ++r) {
                ProcessSingleRow(rowBase + r);
            }
            return;
        }
        const int32_t tileSize = kMergeRowFactor * N;
        CopyInX1(rowBase, tileSize);
        CopyInX2(rowBase, tileSize);
        ComputeRows(tileSize);
        CopyOutGq1(rowBase, tileSize);
        CopyOutGq2(rowBase, tileSize);
        CopyOutY3Fp32(rowBase, tileSize);
        CopyOutY4Dtype(rowBase, tileSize);
        CopyOutXAdd(rowBase, tileSize);
        CopyOutScale1(rowBase, kMergeRowFactor);
        CopyOutScale2(rowBase, kMergeRowFactor);
    }

private:
    int32_t M = 0, N = 0, blockM = 0, usedCoreNum = 0;
    int32_t tasksPerCore = 0, rowFactor = 0;
    float eps = 0.0f, invN = 0.0f, inv127 = 0.0f;
    int32_t subBlockRows_ = 0, rowLoops_ = 0;

    AscendC::TPipe pipe;

    // GM tensors
    AscendC::GlobalTensor<dataType> x1GM_, x2GM_, gammaGM_, betaGM_;
    AscendC::GlobalTensor<dataType> smooth1GM_, smooth2GM_;
    AscendC::GlobalTensor<int8_t> gq1GM_, gq2GM_;
    AscendC::GlobalTensor<float> y3Fp32GM_;
    AscendC::GlobalTensor<dataType> y4DtypeGM_, xAddGM_;
    AscendC::GlobalTensor<float> scale1GM_, scale2GM_;

    // Queues
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_, x2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> gq1OutQueue_, gq2OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> y3OutQueue_, y4OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> xAddOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> scale1OutQueue_, scale2OutQueue_;

    // Pre-loaded buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> gamma1DBuf_, gammaTileBuf_, gammaBcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth2_1DBuf_, smooth2TileBuf_, smooth2BcastTmpBuf_;

    // Compute buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufA_, tempBufB_, tempBufC_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xAddFp32Buf_, yNormFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> quantHalfBuf_, reduceTmpBuf_, bcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_, rstdBuf_, scaleBuf_, maxAbsBuf_;

    // Cast buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_, x2CastBuf_, gammaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smooth1CastBuf_, smooth2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xAddCastBuf_, y4CastBuf_;

    // Locals
    AscendC::LocalTensor<dataType> x1InLocal_, x2InLocal_, gammaInLocal_;
    AscendC::LocalTensor<int8_t> gq1OutLocal_, gq2OutLocal_;
    AscendC::LocalTensor<float> y3OutLocal_;
    AscendC::LocalTensor<dataType> y4OutLocal_, xAddOutLocal_;
    AscendC::LocalTensor<float> scale1OutLocal_, scale2OutLocal_;
    AscendC::LocalTensor<float> gammaFp32Local_, gammaTileLocal_;
    AscendC::LocalTensor<uint8_t> gammaBcastTmpLocal_;
};
